\set ON_ERROR_STOP on
-- Isolated relevant catalog slice, not a complete production schema or real JWT verification.
DO $$ BEGIN IF current_database()<>'saas_primary_test' THEN RAISE EXCEPTION 'DISPOSABLE_TEST_DATABASE_REQUIRED'; END IF; END $$;
CREATE TYPE public.member_role AS ENUM ('owner','admin','editor','author','contributor','viewer');
CREATE TYPE public.site_status AS ENUM ('draft','active','suspended','archived');
CREATE TYPE public.domain_status AS ENUM ('pending','verifying','active','failed','pending_deletion');
ALTER TABLE public.site_members ALTER COLUMN role TYPE public.member_role USING role::public.member_role;
ALTER TABLE public.sites ALTER COLUMN status TYPE public.site_status USING status::public.site_status, ADD COLUMN updated_at timestamptz DEFAULT now();
DROP TRIGGER sync_site_custom_domain_from_domains ON public.site_domains;
ALTER TABLE public.site_domains ALTER COLUMN status TYPE public.domain_status USING status::public.domain_status, ADD COLUMN updated_at timestamptz DEFAULT now(), ADD COLUMN verified_at timestamptz;
INSERT INTO public.site_members VALUES('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000010','owner');
CREATE TABLE public.domain_connection_entitlements(site_id uuid,hostname text);
CREATE TABLE public.domain_migration_locks(site_id uuid,fence uuid);
CREATE FUNCTION private.has_site_role(target_site uuid,allowed_roles public.member_role[]) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT (SELECT auth.uid()) IS NOT NULL AND EXISTS(SELECT 1 FROM public.site_members sm WHERE sm.site_id=target_site AND sm.user_id=(SELECT auth.uid()) AND sm.role=ANY(allowed_roles)); $$;
CREATE FUNCTION private.is_site_member(target_site uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT (SELECT auth.uid()) IS NOT NULL AND EXISTS(SELECT 1 FROM public.site_members sm WHERE sm.site_id=target_site AND sm.user_id=(SELECT auth.uid())); $$;
DROP POLICY site_manager ON public.sites; DROP POLICY domain_manager ON public.site_domains;
CREATE POLICY sites_read_authenticated ON public.sites FOR SELECT TO authenticated USING(owner_id=(SELECT auth.uid()) OR private.is_site_member(id) OR (status='active'::public.site_status AND is_public));
CREATE POLICY sites_update_managers ON public.sites FOR UPDATE TO authenticated USING(private.has_site_role(id,ARRAY['owner','admin']::public.member_role[])) WITH CHECK(private.has_site_role(id,ARRAY['owner','admin']::public.member_role[]));
CREATE POLICY domains_read_members ON public.site_domains FOR SELECT TO authenticated USING(private.is_site_member(site_id));
CREATE POLICY domains_update_admins ON public.site_domains FOR UPDATE TO authenticated USING(private.has_site_role(site_id,ARRAY['owner','admin']::public.member_role[])) WITH CHECK(private.has_site_role(site_id,ARRAY['owner','admin']::public.member_role[]));
ALTER TABLE public.site_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY members_read_site_team ON public.site_members FOR SELECT TO authenticated USING(private.is_site_member(site_id));
CREATE OR REPLACE FUNCTION public.domain_connection_reject_primary_v1() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NEW.is_primary IS TRUE AND NEW.provider IN ('cloudflare','cloudflare-custom-hostnames') AND EXISTS(SELECT 1 FROM public.domain_connection_entitlements e WHERE e.site_id=NEW.site_id AND (NEW.hostname=e.hostname OR NEW.hostname='www.'||e.hostname)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='DOMAIN_CONNECTION_KEEP_FREE_PRIMARY',DETAIL='Paid connection hostnames must remain aliases. Use a connection-aware provider state update with is_primary=false; never promote the custom hostname or clear other primary records.'; END IF; RETURN NEW; END; $$;
CREATE FUNCTION public.domain_connection_reject_site_primary_v1() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NEW.custom_domain IS NOT NULL AND NEW.custom_domain IS DISTINCT FROM OLD.custom_domain AND EXISTS(SELECT 1 FROM public.domain_connection_entitlements e JOIN public.site_domains d ON d.site_id=e.site_id AND (d.hostname=e.hostname OR d.hostname='www.'||e.hostname) WHERE e.site_id=NEW.id AND d.hostname=NEW.custom_domain AND d.provider IN ('cloudflare','cloudflare-custom-hostnames')) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='DOMAIN_CONNECTION_KEEP_FREE_PRIMARY',DETAIL='A paid SaaS connection is an alias, not a replacement for the existing primary address.'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER domain_connection_reject_site_primary_v1 BEFORE UPDATE OF custom_domain ON public.sites FOR EACH ROW EXECUTE FUNCTION public.domain_connection_reject_site_primary_v1();
CREATE FUNCTION private.guard_domain_migration_write() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE ids uuid[];l public.domain_migration_locks%ROWTYPE; BEGIN IF TG_TABLE_NAME='sites' THEN ids:=ARRAY[OLD.id]; ELSIF TG_OP='INSERT' THEN ids:=ARRAY[NEW.site_id]; ELSIF TG_OP='DELETE' THEN ids:=ARRAY[OLD.site_id]; ELSE ids:=ARRAY[OLD.site_id,NEW.site_id]; END IF; PERFORM id FROM public.sites WHERE id=ANY(ids) ORDER BY id FOR UPDATE; FOR l IN SELECT * FROM public.domain_migration_locks WHERE site_id=ANY(ids) LOOP IF NOT(coalesce(current_setting('role',true),'')='service_role' AND coalesce(current_setting('ngeblogging.migration_fence',true),'')=l.fence::text) THEN RAISE EXCEPTION 'DOMAIN_MIGRATION_MAINTENANCE'; END IF; END LOOP; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END; $$;
CREATE TRIGGER guard_domain_migration_write BEFORE INSERT OR DELETE OR UPDATE ON public.site_domains FOR EACH ROW EXECUTE FUNCTION private.guard_domain_migration_write();
CREATE TRIGGER guard_domain_migration_write BEFORE UPDATE ON public.sites FOR EACH ROW EXECUTE FUNCTION private.guard_domain_migration_write();
CREATE FUNCTION private.sync_site_custom_domain_from_domains() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='public','private','pg_temp' AS $$ DECLARE target_site_id uuid; previous_hostname text; next_hostname text; BEGIN IF TG_OP='DELETE' THEN target_site_id:=OLD.site_id;previous_hostname:=OLD.hostname; ELSE target_site_id:=NEW.site_id;previous_hostname:=CASE WHEN TG_OP='INSERT' THEN NULL ELSE OLD.hostname END; END IF; IF TG_OP<>'DELETE' THEN IF NEW.status='active'::domain_status AND NEW.is_primary IS TRUE THEN UPDATE public.sites SET custom_domain=NEW.hostname,updated_at=now() WHERE id=NEW.site_id AND custom_domain IS DISTINCT FROM NEW.hostname; RETURN NEW; END IF; END IF; IF previous_hostname IS NOT NULL THEN SELECT d.hostname INTO next_hostname FROM public.site_domains d WHERE d.site_id=target_site_id AND d.status='active'::domain_status AND d.is_primary IS TRUE ORDER BY d.verified_at DESC NULLS LAST,d.updated_at DESC LIMIT 1; UPDATE public.sites SET custom_domain=next_hostname,updated_at=now() WHERE id=target_site_id AND custom_domain=previous_hostname AND custom_domain IS DISTINCT FROM next_hostname; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END; $$;
CREATE TRIGGER sync_site_custom_domain_from_domains AFTER INSERT OR DELETE OR UPDATE OF status,is_primary,hostname ON public.site_domains FOR EACH ROW EXECUTE FUNCTION private.sync_site_custom_domain_from_domains();
CREATE FUNCTION public.handoff_expect(action text,expected_code text,expected_message text DEFAULT NULL) RETURNS void LANGUAGE plpgsql AS $$ DECLARE actual_code text;actual_message text; BEGIN BEGIN EXECUTE action; EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS actual_code=RETURNED_SQLSTATE,actual_message=MESSAGE_TEXT; END; IF actual_code IS DISTINCT FROM expected_code OR (expected_message IS NOT NULL AND actual_message IS DISTINCT FROM expected_message) THEN RAISE EXCEPTION 'Expected % / %, got % / %',expected_code,expected_message,actual_code,actual_message; END IF; END; $$;
CREATE FUNCTION public.handoff_assert_active() RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.site_domains WHERE hostname='source.ngeblogging.com' AND status='active' AND NOT is_primary) OR NOT EXISTS(SELECT 1 FROM public.site_domains WHERE hostname='www.example.test' AND status='active' AND is_primary) OR NOT EXISTS(SELECT 1 FROM public.sites WHERE custom_domain='www.example.test' AND status='active' AND is_public) OR (SELECT count(*) FROM public.site_domains WHERE is_primary)<>1 THEN RAISE EXCEPTION 'CATALOG_ACTIVATION_ASSERTION_FAILED'; END IF; END; $$;
BEGIN; SET LOCAL ROLE authenticated; SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000010',true);
UPDATE public.site_domains SET status='active',provider_status='active',ssl_status='active',is_primary=true WHERE hostname='www.example.test'; SELECT public.handoff_assert_active(); ROLLBACK;
BEGIN; SET LOCAL ROLE authenticated; SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000011',true);
UPDATE public.site_domains SET status='active',provider_status='active',ssl_status='active',is_primary=true WHERE hostname='www.example.test'; SELECT public.handoff_assert_active(); ROLLBACK;
BEGIN; INSERT INTO public.domain_connection_entitlements VALUES('00000000-0000-0000-0000-000000000001','example.test'); SET LOCAL ROLE authenticated; SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000010',true);
SELECT public.handoff_expect($a$UPDATE public.site_domains SET status='active',provider_status='active',ssl_status='active',is_primary=true WHERE hostname='www.example.test'$a$,'23514','DOMAIN_CONNECTION_KEEP_FREE_PRIMARY');
SELECT public.handoff_expect($a$UPDATE public.sites SET custom_domain='www.example.test' WHERE slug='source'$a$,'23514','DOMAIN_CONNECTION_KEEP_FREE_PRIMARY'); ROLLBACK;
BEGIN; INSERT INTO public.domain_migration_locks VALUES('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000301'); SET LOCAL ROLE authenticated; SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000010',true);
SELECT public.handoff_expect($a$UPDATE public.site_domains SET status='active',provider_status='active',ssl_status='active',is_primary=true WHERE hostname='www.example.test'$a$,'P0001','DOMAIN_MIGRATION_MAINTENANCE'); ROLLBACK;
BEGIN; SET LOCAL ROLE authenticated; SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000010',true); SELECT set_config('test.fail_mapping','on',true);
SELECT public.handoff_expect($a$UPDATE public.site_domains SET status='active',provider_status='active',ssl_status='active',is_primary=true WHERE hostname='www.example.test'$a$,'P0001','FORCED_MAPPING_FAILURE');
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.site_domains WHERE hostname='source.ngeblogging.com' AND is_primary AND status='active') OR NOT EXISTS(SELECT 1 FROM public.site_domains WHERE hostname='www.example.test' AND NOT is_primary AND status='verifying') OR NOT EXISTS(SELECT 1 FROM public.sites WHERE custom_domain='source.ngeblogging.com') THEN RAISE EXCEPTION 'CATALOG_ROLLBACK_FAILED'; END IF; END $$; ROLLBACK;
